# -*- coding: utf-8 -*-
# GENERATED BY AI
"""Tests for connector pinout rendering from KiCad footprints."""

from pathlib import Path

import pytest

from kiutils.footprint import Footprint

from wireviz.wv_footprint import footprint_image, render_footprint_svg

FIXTURE = (
    Path(__file__).parent.parent
    / "examples"
    / "resources"
    / "kicad-footprints"
    / "DemoHeader.pretty"
    / "DemoHeader_1x04_P2.54mm.kicad_mod"
)


@pytest.fixture
def footprint():
    return Footprint.from_file(str(FIXTURE))


def test_render_footprint_svg(footprint):
    svg, width_mm, height_mm = render_footprint_svg(footprint)
    assert svg.startswith("<svg")
    assert svg.endswith("</svg>")
    # one connector housing, no PCB footprint graphics
    assert svg.count("<rect") == 1
    assert svg.count("<line") == 0
    # 4 pins and 4 contact holes
    assert svg.count("<circle") == 8
    # pin 1 is marked with a thicker outline
    assert "#111111" in svg
    # pin numbers 1 to 4
    for number in ("1", "2", "3", "4"):
        assert f">{number}</text>" in svg
    # the connector is wider than tall
    assert width_mm > height_mm


def test_footprint_image():
    image = footprint_image(
        {"library": str(FIXTURE.parent), "part": FIXTURE.stem, "width": 150}
    )
    assert image.src.endswith(".svg")
    assert Path(image.src).is_file()
    assert image.width == 150
    assert image.height > 0
    # height follows the connector aspect ratio (wider than tall)
    assert image.width > image.height


def test_footprint_image_unknown_attribute():
    with pytest.raises(ValueError):
        footprint_image(
            {"library": str(FIXTURE.parent), "part": FIXTURE.stem, "foo": 1}
        )
